function startDrive(free){mode=free?'roam':'race';paused=false;speed=0;elapsed=0;worldPos=0;offset=0;steer=0;night=world===0;document.getElementById('home').style.display='none';document.getElementById('bottomline').style.display='none';document.getElementById('worlds').style.display='none';document.querySelector('.worldtitle').style.display='none';document.getElementById('hud').classList.add('active');document.getElementById('hudMode').textContent=free?'FREE ROAM':'WORLD TOUR';document.getElementById('distanceLabel').textContent=free?'OPEN ROAD':'DISTANCE DRIVEN';document.getElementById('recordLabel').textContent=free?'DAY / NIGHT CYCLE':'SESSION TIME';updateLocation();document.getElementById('hint').textContent='WASD OR ARROW KEYS TO DRIVE';document.getElementById('hint').classList.add('show');setTimeout(()=>document.getElementById('hint').classList.remove('show'),2500)}
function updateLocation(){let w=worlds[world];document.getElementById('regionLabel').textContent=`${w.country} / ${w.city}`;document.getElementById('placeLabel').textContent=w.name;document.getElementById('timeLabel').textContent=night?'NIGHT DRIVE':'GOLDEN HOUR'}
function exitDrive(){mode='menu';paused=false;document.getElementById('home').style.display='flex';document.getElementById('bottomline').style.display='flex';document.getElementById('worlds').style.display='flex';document.querySelector('.worldtitle').style.display='block';document.getElementById('hud').classList.remove('active');document.getElementById('pauseveil').classList.remove('show');for(let k in input)input[k]=false;draw(0)}
function pause(){if(mode==='menu')return;paused=!paused;document.getElementById('pauseveil').classList.toggle('show',paused);if(!paused){last=performance.now()}}
function toast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1900)}
function frame(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;if(mode!=='menu'&&!paused){let accelerate=input.gas||input.up, braking=input.brake||input.down;if(accelerate)speed=Math.min(speed+dt*52,cars[car].power*2.35);else speed=Math.max(0,speed-dt*(mode==='race'?7:4));if(braking)speed=Math.max(0,speed-dt*105);let direction=(input.right?1:0)-(input.left?1:0);steer+=(direction-steer)*Math.min(1,dt*4);offset+=steer*dt*(speed/125);offset-=offset*dt*.2;offset=Math.max(-1.6,Math.min(1.6,offset));worldPos+=speed*dt*5.2;elapsed+=dt;drift=Math.abs(offset);if(mode==='race'&&Math.abs(offset)>1.17){speed=Math.max(speed-35*dt,35);if(Math.abs(offset)>1.55)offset*=.97}if(Math.floor(elapsed)%47===0&&Math.floor(elapsed)>0&&Math.floor(elapsed)!==Math.floor(elapsed-dt)){night=!night;updateLocation()}document.getElementById('speed').innerHTML=`${String(Math.round(speed)).padStart(3,'0')}<small> KM/H</small>`;document.getElementById('gear').textContent=speed<1?'N':String(Math.min(7,Math.max(1,Math.floor(speed/34)+1)));document.getElementById('rpm').textContent=String(Math.round(1000+speed*37+Math.sin(t*.02)*90)).padStart(4,'0');document.getElementById('distance').innerHTML=`${(worldPos/1000).toFixed(1)} <small>KM</small>`;let m=Math.floor(elapsed/60),s=Math.floor(elapsed%60);document.getElementById('bestTime').textContent=`${m}:${String(s).padStart(2,'0')}`;document.getElementById('progress').style.width=`${(Math.sin(worldPos*.0003)*50+50)}%`}
 draw(dt);requestAnimationFrame(frame)}requestAnimationFrame(frame);
document.getElementById('driveBtn').onclick=()=>startDrive(false);document.getElementById('freeBtn').onclick=()=>startDrive(true);document.getElementById('pauseBtn').onclick=pause;document.getElementById('resumeBtn').onclick=pause;document.getElementById('exitBtn').onclick=exitDrive;document.getElementById('prevCar').onclick=()=>{car=(car+cars.length-1)%cars.length;color=0;carColor=cars[car].colors[color];renderCar()};document.getElementById('nextCar').onclick=()=>{car=(car+1)%cars.length;color=0;carColor=cars[car].colors[color];renderCar()};document.getElementById('audioBtn').onclick=()=>{mute=!mute;document.getElementById('audioBtn').textContent=mute?'♫':'♪';toast(mute?'AUDIO MUTED':'ENGINE AUDIO ON')};document.getElementById('swatches').addEventListener('click',e=>{let b=e.target.closest('.swatch');if(!b)return;color=[...b.parentElement.children].indexOf(b);carColor=cars[car].colors[color];renderCar()});
function key(e,on){let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(k==='w'||k==='arrowup')input.up=on;if(k==='s'||k==='arrowdown')input.down=on;if(k==='a'||k==='arrowleft')input.left=on;if(k==='d'||k==='arrowright')input.right=on;if(k===' '&&on)pause();if(k==='escape'&&on)pause();if(k==='n'&&on){night=!night;updateLocation();toast(night?'NIGHT MODE':'DAY MODE')}}addEventListener('keydown',e=>key(e,true));addEventListener('keyup',e=>key(e,false));document.querySelectorAll('.touch-controls button').forEach(b=>{let k=b.dataset.key;const set=(on)=>{input[k]=on};b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);set(true)});b.addEventListener('pointerup',()=>set(false));b.addEventListener('pointercancel',()=>set(false));b.addEventListener('lostpointercapture',()=>set(false))});
renderCar();renderWorlds();draw(0);addEventListener('keydown',e=>{if(e.key==='n'&&mode==='menu'){night=!night;draw(0);toast(night?'NIGHT PREVIEW':'DAY PREVIEW')}if(e.key==='Escape'&&mode==='menu'&&paused)exitDrive()});
})();
